const TEXT: Readonly<Record<string, Readonly<Record<ToolTextKey, string>>>> = { 'zh-CN': ZH, 'zh-TW': ZH_TW, en: EN, ja: JA, ko: KO, es: ES, fr: FR, de: DE, 'pt-BR': PT_BR, ru: RU, ar: AR, hi: HI };
export const COMIC_CANVAS_TOOL_LOCALES = Object.keys(TEXT);

function uncheckedToolText(locale: string, key: ToolTextKey, values?: Readonly<Record<string, string | number>>): string {
    const raw = (TEXT[locale] ?? (locale.startsWith('zh') ? TEXT['zh-CN'] : undefined))?.[key];
    if (typeof raw !== 'string') throw new Error('missing');
    return raw.replace(/\{(\w+)\}/g, (match, name: string) => values && values[name] !== undefined ? String(values[name]) : match);
}

export function toolText(locale: string, key: ToolTextKey, ...rest: AfterLocaleAndKey<Parameters<typeof uncheckedToolText>>): string {
    return totalCopy(locale, key, language => uncheckedToolText(language, key, ...rest));
}
